import React from 'react';

const styles = {
  section: {
    padding: '48px 24px',
    backgroundColor: '#ffffff',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  h2: {
    fontSize: '2rem',
    fontWeight: 'bold',
    color: '#2d3748',
    marginBottom: '8px',
  },
  h3: {
    fontSize: '2rem',
    fontWeight: 'bold',
    color: '#00796b', // Matching teal color
    marginBottom: '24px',
  },
  textContent: {
    color: '#4a5568',
    fontSize: '1.1rem',
    lineHeight: '1.6',
    maxWidth: '800px',
  },
  button: {
    backgroundColor: '#e2e8f0',
    color: '#2d3748',
    fontWeight: 'bold',
    padding: '10px 20px',
    borderRadius: '6px',
    border: '1px solid #cbd5e0',
    cursor: 'pointer',
    marginTop: '24px',
  },
};

const Hero = () => {
  return (
    <section id="about" style={styles.section}>
      <div style={styles.container}>
        <h2 style={styles.h2}>Getting to Know</h2>
        <h3 style={styles.h3}>"Coimbatore Dietitian Pradeepa"</h3>
        <div style={styles.textContent}>
          <p>
            <strong>Pradeepa Saravanan</strong> is a Coimbatore-based consultant Dietitian/Nutritionist...
          </p>
          <p style={{ marginTop: '16px' }}>
            She says, Diet is the cornerstone of health and vitality...
          </p>
          <button style={styles.button}>
            How do you feel being a dietitian?
          </button>
        </div>
      </div>
    </section>
  );
};

export default Hero;
